// Health Informatics Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: hospital statistics, data quality and security cases.
import {q, mix} from './q.js';
const ZC='Zhou & Clack, Introduction to Healthcare Informatics (AHIMA)', WH='White, A Practical Approach to Analyzing Healthcare Data (AHIMA)';
const HIST='History, Careers, and Roles', SYS='Information Systems in Healthcare', DA='Data Analytics', DQ='Data Integrity and Quality', GOV='Data Governance', SEC='Health Information Privacy & Security', ETH='Ethics', RES='Research Study and Design', EMER='Emerging Technologies';

export default {
 id:'health-informatics-1',
 event:'Health Informatics',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Zhou & Clack’s Introduction to Healthcare Informatics and White’s A Practical Approach to Analyzing Healthcare Data (AHIMA)',
 plan:[{area:HIST,weight:8},{area:SYS,weight:12},{area:DA,weight:28},{area:DQ,weight:8},{area:GOV,weight:12},{area:SEC,weight:12},{area:ETH,weight:4},{area:RES,weight:12},{area:EMER,weight:4}],
 questions:mix([
  q(HIST,'Which professional association awards the RHIA and RHIT credentials?','AHIMA',['HIMSS','AMA','AAMA'],'B','The American Health Information Management Association credentials health information professionals. HIMSS focuses on health IT and systems.',ZC),
  q(HIST,'Which 2009 law offered financial incentives for hospitals and providers to adopt electronic health records?','The HITECH Act',['HIPAA','The Affordable Care Act','The Patient Self-Determination Act'],'D','HITECH’s Meaningful Use (now Promoting Interoperability) program paid incentives for certified EHR use.',ZC),
  q(HIST,'What does health informatics focus on?','Using information to improve health care',['Repairing hospital equipment','Billing patients and insurers only','Performing laboratory tests'],'A','Informatics combines health sciences, information science and computer science to manage data and support decisions.',ZC),
  q(HIST,'Which leader usually bridges clinicians and IT in planning and adopting clinical information systems?','Chief Medical Information Officer',['Chief Financial Officer','Facilities manager','Admissions clerk'],'C','The CMIO, typically a physician, guides EHR design, clinical decision support and clinician adoption.',ZC),
  q(SYS,'How does an electronic health record (EHR) differ from an electronic medical record (EMR)?','An EHR is built to share across organizations',['An EHR is used only by one practice','An EHR stores only billing data','They have no differences in scope'],'B','An EMR is a digital chart within one practice. An EHR follows the patient and is built to exchange data among providers.',ZC),
  q(SYS,'What is a main safety benefit of computerized provider order entry (CPOE)?','It reduces handwriting and order errors',['It replaces the pharmacists','It removes the need for physicians','It prints paper charts faster'],'D','CPOE lets providers enter orders electronically and often links to decision support for allergies, interactions and dosing.',ZC),
  q(SYS,'An EHR displays an alert when a prescribed drug interacts with another of the patient’s medications. What is this?','Clinical decision support',['A data warehouse','A master patient index','An audit trail'],'A','CDS gives clinicians knowledge at the point of care, but too many alerts can cause alert fatigue.',ZC),
  q(SYS,'Which standard is designed to let health data be exchanged through modern web-based application programming interfaces (APIs)?','FHIR',['ICD-10-CM','CPT','SNOMED CT only'],'C','HL7’s Fast Healthcare Interoperability Resources (FHIR) defines data “resources” that apps and systems can share.',ZC),
  q(SYS,'What is a health information exchange (HIE)?','A system for sharing records across providers',['A stock market for hospitals','A billing clearinghouse for insurers only','A medical school'],'B','HIEs give clinicians access to records from other facilities, reducing repeat tests and improving care.',ZC),
  q(SYS,'Which system stores and displays medical images such as X-rays and CT scans?','PACS',['LIS','CPOE','MPI'],'D','A Picture Archiving and Communication System stores and distributes images. A laboratory information system manages lab data.',ZC),
  q(DA,'Lengths of stay for five patients are 2, 3, 3, 4 and 13 days. Which measure best represents the typical stay?','The median, 3 days',['The mean, 5 days','The range, 11 days','The mode, 13 days'],'A','The outlier (13 days) pulls the mean up to 5. The median is less affected by extreme values.',WH),
  q(DA,'A hospital had 1,200 inpatient days and 300 discharges in a month. What was the average length of stay?','4.0 days',['0.25 days','40 days','3.0 days'],'C','Average length of stay = total length of stay (discharge days) ÷ number of discharges = 1,200 ÷ 300 = 4.0 days.',WH),
  q(DA,'A 100-bed hospital had 2,250 inpatient service days in a 30-day month. What was the bed occupancy rate?','75%',['22.5%','85%','133%'],'B','Occupancy = service days ÷ (beds × days) × 100 = 2,250 ÷ (100 × 30) × 100 = 75%.',WH),
  q(DA,'A hospital had 6 deaths among 400 discharges (including deaths). What is the gross death rate?','1.5%',['0.15%','6%','15%'],'D','Gross death rate = deaths ÷ discharges × 100 = 6 ÷ 400 × 100 = 1.5%.',WH),
  q(DA,'What does a small standard deviation tell you about a data set?','The values are clustered close to the mean',['The values are spread far from the mean','The mean is always zero','The data contain errors'],'A','Standard deviation measures spread. A larger standard deviation means more variability.',WH),
  q(DA,'Patient pain ratings of mild, moderate and severe are which type of data?','Ordinal',['Nominal','Interval','Ratio'],'C','Ordinal data have a meaningful order but unequal gaps between categories. Nominal data are categories with no order, such as blood type.',WH),
  q(DA,'Which chart is best for showing the distribution of a continuous variable, such as patient ages?','Histogram',['Pie chart','Line chart with one point','Bar chart of categories'],'B','Histograms group continuous values into ranges. Bar charts compare separate categories.',WH),
  q(DA,'Which chart is most appropriate for showing monthly infection rates over two years?','Line chart',['Pie chart','Scatter plot of unrelated variables','Histogram of ages'],'D','Line charts connect values in time order, making rises, falls and seasonal patterns easy to see.',WH),
  q(DA,'A model uses past data to estimate which patients are likely to be readmitted. What type of analytics is this?','Predictive analytics',['Descriptive analytics','Prescriptive analytics','Diagnostic coding'],'A','Descriptive analytics summarizes what happened, predictive estimates what will happen, and prescriptive recommends actions.',WH),
  q(DA,'In a normal distribution, about what percentage of values fall within one standard deviation of the mean?','68%',['50%','95%','99.7%'],'C','About 68% fall within ±1 SD, 95% within ±2 SD and 99.7% within ±3 SD.',WH),
  q(DA,'A study finds a correlation coefficient of r = −0.8 between exercise minutes and blood pressure. What does this show?','A strong negative relationship',['A weak positive relationship','No relationship','Proof that exercise causes lower blood pressure'],'B','r ranges from −1 to +1; −0.8 is strong and negative. Correlation alone does not prove causation.',WH),
  q(DA,'A hospital had 900 discharges and 45 patients were readmitted within 30 days. What is the 30-day readmission rate?','5%',['2%','20%','45%'],'D','Readmission rate = readmissions ÷ discharges × 100 = 45 ÷ 900 × 100 = 5%.',WH),
  q(DA,'Comparing a hospital’s infection rate with rates at similar hospitals is called:','Benchmarking',['Encryption','Data mining only','Auditing access logs'],'A','Benchmarking compares performance with peers or standards to find areas for improvement.',WH),
  q(DA,'Why is a pie chart a poor choice for showing changes in admissions over 12 months?','Pie charts show parts of a whole, not trends over time',['Pie charts cannot show numbers','Pie charts work only for ages','Pie charts must have exactly 12 slices'],'C','Pie charts compare proportions at one point in time. Line charts better show change over time.',WH),
  q(DQ,'A record lists a patient’s discharge date as two days before the admission date. Which data quality dimension is violated?','Accuracy',['Timeliness','Accessibility','Granularity'],'B','The data are not logically possible. Validation rules in the system can catch such errors at entry.',ZC),
  q(DQ,'A patient has two different medical record numbers in the same hospital. Which tool is cleaned up to fix this?','The master patient index',['The chargemaster','The data warehouse only','The staffing schedule'],'D','Duplicate records split a patient’s information and create safety risks. The MPI links each patient to one identifier.',ZC),
  q(DQ,'What is a risk of copying and pasting old notes into new EHR documentation?','Outdated information is carried forward',['Notes become shorter','Records are always more accurate','It improves billing compliance'],'A','“Cloned” notes can repeat old findings, misrepresent care and create legal and billing problems.',ZC),
  q(DQ,'A lab result is entered into the EHR three days after the test. Which data quality characteristic is lacking?','Timeliness',['Completeness','Accuracy','Relevance'],'C','Data must be available when needed for decisions. Late data can delay treatment.',ZC),
  q(GOV,'What is data governance?','Policies for managing data as an asset',['A type of database software','A law that requires EHRs','A hospital billing method'],'B','Data governance defines who can take what actions with which data, ensuring quality, security and appropriate use.',ZC),
  q(GOV,'Who is responsible for the day-to-day quality and appropriate use of a specific data set?','Data steward',['Patient','Software vendor only','Hospital volunteer'],'D','Data stewards oversee definitions, quality and use of data within their area, supporting governance policies.',ZC),
  q(GOV,'What does a data dictionary describe?','Definitions and formats of data elements',['A list of all patients','The hospital’s spending','The list of user security passwords'],'A','A data dictionary ensures everyone uses data elements consistently, such as the format for a date of birth.',ZC),
  q(GOV,'What is the legal health record?','The organization’s defined official record',['Any note written on paper','Only the billing statement','The patient’s personal health diary'],'C','Organizations define which information makes up the legal record for disclosure and legal purposes.',ZC),
  q(GOV,'Why do organizations set record retention policies?','To keep records for the required time',['To keep records forever','To delete records after one week','To avoid storing medical images'],'B','Retention periods are set by federal and state law and accreditation standards. Secure destruction protects privacy.',ZC),
  q(GOV,'What is metadata?','Data that describe other data',['Data about a patient’s diet','A type of computer virus or malware','The final diagnosis only'],'D','Metadata, such as timestamps and authors, support audits, data quality and legal use of records.',ZC),
  q(SEC,'Which three types of safeguards does the HIPAA Security Rule require?','Administrative, physical and technical',['Financial, clinical and legal','Public, private and personal','Federal, state and local'],'A','Examples include training (administrative), locked server rooms (physical) and encryption and access controls (technical).',ZC),
  q(SEC,'Encrypting patient data on laptops is an example of which HIPAA safeguard?','Technical',['Administrative','Physical','Financial'],'C','Technical safeguards protect electronic data. Encryption also means a lost device may not count as a reportable breach.',ZC),
  q(SEC,'A registration clerk can see demographics but not clinical notes. Which security principle is this?','Role-based access',['Open access','Data mining','Interoperability'],'B','Role-based access limits users to the information needed for their job, supporting the minimum necessary standard.',ZC),
  q(SEC,'Which tool records who viewed or changed a patient’s electronic record and when?','Audit trail',['Firewall','Data dictionary','Backup tape'],'D','Audit logs help detect inappropriate access, such as employees viewing records without a work reason.',ZC),
  q(SEC,'An employee receives an email that appears to be from IT asking for her password. What is this?','Phishing',['Encryption','A firewall','A backup'],'A','Phishing tricks users into revealing credentials or clicking harmful links. Staff training is a key defense.',ZC),
  q(SEC,'A breach of unsecured health information affects more than 500 people in one state. What must the organization do?','Notify affected people, HHS and prominent media',['Notify no one if the breach was accidental','Notify only the IT department','Wait one year before notifying'],'C','The HIPAA Breach Notification Rule requires notice without unreasonable delay and no later than 60 days after discovery.',ZC),
  q(ETH,'An employee looks up a celebrity patient’s record out of curiosity. What is the problem?','It is unauthorized access',['It is allowed if no one finds out','It is acceptable for all employees','It is required for quality checks'],'B','Viewing records without a work-related need violates HIPAA and the AHIMA Code of Ethics and can lead to firing and penalties.',ZC),
  q(ETH,'A predictive algorithm was trained mostly on data from one population and performs poorly for others. What ethical concern does this raise?','Algorithmic bias',['Data encryption','Interoperability','Benchmarking'],'D','Biased training data can lead to unfair recommendations. Testing models across groups helps identify and reduce bias.',ZC),
  q(RES,'Which group must review and approve research involving human subjects to protect participants?','Institutional Review Board (IRB)',['Hospital billing office','Medical staff credentialing committee','Information technology help desk'],'A','IRBs review risks, benefits and informed consent before research begins.',ZC),
  q(RES,'Under HIPAA’s safe harbor method, how is health data de-identified?','By removing 18 identifiers',['By encrypting the file','By removing only the name','By adding fake data'],'C','Identifiers include names, small geographic areas, dates (except year), phone numbers and record numbers.',ZC),
  q(RES,'Researchers review past medical records to see whether patients on a drug had more falls. What type of study is this?','Retrospective study',['Prospective randomized trial','Laboratory experiment','Case report of one patient'],'B','Retrospective studies analyze existing data from the past. They are efficient but limited by what was recorded.',WH),
  q(RES,'In a randomized controlled trial, why are participants assigned to groups at random?','To balance other factors between groups',['To make the study cheaper','To ensure everyone gets the treatment','To avoid needing informed consent'],'D','Randomization reduces selection bias and confounding, so the groups differ mainly in whether they received the intervention.',WH),
  q(RES,'A study reports p = 0.03. Using the common 0.05 threshold, what does this mean?','The result is statistically significant',['The result is not significant','The study was 3% complete','The effect is clinically important by definition'],'A','A p-value below 0.05 suggests the result is unlikely due to chance alone. Statistical significance is not the same as clinical importance.',WH),
  q(RES,'In a study of a new diabetes app, what does the null hypothesis state?','The app has no effect on blood glucose',['The app definitely lowers blood glucose','The app raises blood glucose','The study will be published'],'C','Researchers test whether data provide enough evidence to reject the null hypothesis of no effect.',WH),
  q(EMER,'A hospital uses machine learning to flag patients at risk of sepsis before obvious symptoms appear. What technology is this?','Artificial intelligence',['Paper-based charting','Fax transmission of records','Manual chart review only'],'B','AI models find patterns in large data sets. They must be validated and monitored for accuracy and bias.',ZC),
  q(EMER,'A patient with heart failure sends daily weight and blood pressure readings from home to the care team. What is this?','Remote patient monitoring',['A data dictionary','A master patient index','Batch billing'],'D','Remote monitoring lets clinicians spot problems early and can reduce hospital readmissions.',ZC)
 ],173)
};
